using System.ComponentModel.DataAnnotations;

namespace LocalizationDemo.Models;

public class Product
{
    [Required(ErrorMessage = "Product name is required")]
    [StringLength(100, ErrorMessage = "Product name must be under 100 characters")]
    [Display(Name = "Product Name")]
    public string Name { get; set; } = string.Empty;

    [Range(0.01, 9999.99, ErrorMessage = "Price must be between {0} and {1}")]
    [Display(Name = "Price")]
    public decimal Price { get; set; }

    [EmailAddress(ErrorMessage = "Invalid supplier email address")]
    [Display(Name = "Supplier Email")]
    public string SupplierEmail { get; set; } = string.Empty;
}

using Microsoft.Extensions.Localization;
using System.ComponentModel.DataAnnotations;

namespace LocalizationDemo.Validation;

public class FrenchPhoneAttribute : ValidationAttribute
{
    protected override ValidationResult IsValid(object? value, ValidationContext context)
    {
        var localizer = context.GetService<IStringLocalizer<SharedResource>>();
        if (localizer == null)
        {
            return new ValidationResult("Localization service unavailable");
        }

        if (value is not string phone || string.IsNullOrWhiteSpace(phone))
        {
            return ValidationResult.Success;
        }

        // French phone numbers: 10 digits, optionally starting with +33
        var digits = new string(phone.Where(char.IsDigit).ToArray());
        var isValid = digits.Length == 10 || (digits.Length == 11 && digits.StartsWith("33"));

        if (!isValid)
        {
            var errorMessage = localizer["InvalidFrenchPhone"];
            return new ValidationResult(errorMessage);
        }

        return ValidationResult.Success;
    }
}

using System.ComponentModel.DataAnnotations;
using LocalizationDemo.Resources; // namespace of your .resx file

namespace LocalizationDemo.Models;

