        ErrorMessageResourceName = "CustomerNameRequired",
        ErrorMessageResourceType = typeof(ValidationMessages))]
    [Display(Name = "Customer Name", ResourceType = typeof(DisplayMessages))]
    public string Name { get; set; } = string.Empty;

    [Range(18, 120,
        ErrorMessageResourceName = "AgeRange",
        ErrorMessageResourceType = typeof(ValidationMessages))]
    [Display(Name = "Age", ResourceType = typeof(DisplayMessages))]
    public int Age { get; set; }
}

